<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import DataGrid, { type GridColumn } from "@/components/DataGrid.vue";
import { ApiError } from "@/services/http";
import { useAuthSession } from "@/composables/useAuthSession";
import { createAsignacion, getAccessOptions, getAssignmentOptions, getTarjeta, listCardHistory, listValidRequests, type HistorialPaginated, type PerfilAcceso, type SolicitudAsignable, type Tarjeta } from "@/services/tarjetas";
import { searchBeneficiaries, type BeneficiarySearchResult } from "@/services/beneficiarios";

const route = useRoute(); const router = useRouter(); const session = useAuthSession();
const id = String(route.params.id); const card = ref<Tarjeta | null>(null); const tab = ref<"assignment" | "history">("assignment");
const loading = ref(true); const saving = ref(false); const error = ref(""); const success = ref("");
const search = ref(""); const results = ref<BeneficiarySearchResult[]>([]); const resultPage = ref(1); const resultPages = ref(0); const resultLoading = ref(false); const resultError = ref(""); const selected = ref<BeneficiarySearchResult | null>(null); const requests = ref<SolicitudAsignable[]>([]); const requestLoading = ref(false);
const profiles = ref<PerfilAcceso[]>([]); const options = ref<{ tiposVigencia: Array<{ idTipoValor: number; nombreTipoValor: string }>; estadosAsignacion: Array<{ idTipoValor: number; nombreTipoValor: string }> }>({ tiposVigencia: [], estadosAsignacion: [] });
const history = ref<HistorialPaginated[]>([]); const historyPage = ref(1); const historyPages = ref(0); const historyTotal = ref(0); const historyLoading = ref(false); const historyError = ref("");
const form = ref({ idSolicitud: "", idTipoVigencia: 0, idEstadoAsignacion: 0, idPerfilAcceso: "", fechaInicioVigencia: new Date().toISOString().slice(0, 10), fechaFinVigencia: "" });
const historyColumns: GridColumn[] = [{ key: "fecha", label: "Fecha", width: "15%" }, { key: "tipo", label: "Tipo", width: "10%" }, { key: "nombreBeneficiario", label: "Beneficiario", width: "17%" }, { key: "codigoSolicitud", label: "Solicitud", width: "12%" }, { key: "perfilesAcceso", label: "Perfil", width: "14%" }, { key: "vigencia", label: "Vigencia", width: "17%" }, { key: "nombreEstadoAsignacion", label: "Estado", width: "10%" }, { key: "usuarioResponsable", label: "Responsable", width: "15%" }];
let searchTimer: ReturnType<typeof setTimeout> | undefined; let searchController: AbortController | undefined; let searchSequence = 0;
const message = (e: unknown) => e instanceof ApiError ? e.message : "Ocurrió un error inesperado";
const canAssign = computed(() => session.user.value?.permissions.includes("TARJETAS_ASIGNAR") ?? false);
const valid = computed(() => Boolean(card.value?.estadoTarjeta && !card.value.idAsignacion && selected.value && form.value.idSolicitud && form.value.idTipoVigencia && form.value.idEstadoAsignacion && form.value.fechaInicioVigencia && (!form.value.fechaFinVigencia || form.value.fechaFinVigencia >= form.value.fechaInicioVigencia)));
function masked(value: string | null) { return value ?? "No disponible"; }
async function loadCard() { try { card.value = await getTarjeta(id); } catch (e) { error.value = message(e); } finally { loading.value = false; } }
async function loadSetup() { try { options.value = await getAssignmentOptions(); profiles.value = (await getAccessOptions()).perfilesAcceso; } catch (e) { error.value = message(e); } }
async function findBeneficiaries(page = 1) { if (search.value.trim().length < 2) { results.value = []; return; } searchController?.abort(); const controller = new AbortController(); searchController = controller; const sequence = ++searchSequence; resultLoading.value = true; resultError.value = ""; try { const response = await searchBeneficiaries(search.value.trim(), page, controller.signal); if (sequence !== searchSequence) return; results.value = response.items; resultPage.value = response.pagination.page; resultPages.value = response.pagination.totalPages; } catch (e) { if ((e as Error).name !== "AbortError") resultError.value = message(e); } finally { if (sequence === searchSequence) resultLoading.value = false; } }
watch(search, () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => void findBeneficiaries(1), 350); });
async function choose(item: BeneficiarySearchResult) { selected.value = item; requests.value = []; form.value.idSolicitud = ""; requestLoading.value = true; try { requests.value = await listValidRequests(item.idBeneficiario); } catch (e) { error.value = message(e); } finally { requestLoading.value = false; } }
async function loadHistory(page = 1) { historyLoading.value = true; historyError.value = ""; history.value = []; try { const response = await listCardHistory(id, page); history.value = response.items; historyPage.value = page; historyPages.value = response.pagination.totalPages; historyTotal.value = response.pagination.total; } catch (e) { historyError.value = message(e); } finally { historyLoading.value = false; } }
function historyRow(item: HistorialPaginated): Record<string, unknown> { return { ...item, fecha: new Date(item.fechaAsignacion).toLocaleString("es-HN"), tipo: "Asignación", vigencia: `${item.fechaInicioVigencia?.slice(0, 10)} — ${item.fechaFinVigencia?.slice(0, 10) ?? "Sin vencimiento"}` }; }
async function assign() { if (!valid.value || !selected.value || !card.value || !confirm(`¿Confirmar la asignación de la tarjeta ${card.value.codigoTarjeta} a ${selected.value.nombreCompleto}?`)) return; saving.value = true; error.value = ""; try { await createAsignacion({ idTarjeta: id, idBeneficiario: selected.value.idBeneficiario, idSolicitud: form.value.idSolicitud, idTipoVigencia: form.value.idTipoVigencia, idEstadoAsignacion: form.value.idEstadoAsignacion, fechaAsignacion: new Date().toISOString(), fechaInicioVigencia: new Date(`${form.value.fechaInicioVigencia}T00:00:00`).toISOString(), fechaFinVigencia: form.value.fechaFinVigencia ? new Date(`${form.value.fechaFinVigencia}T00:00:00`).toISOString() : null, idPerfilAcceso: form.value.idPerfilAcceso ? Number(form.value.idPerfilAcceso) : null }); success.value = "Asignación registrada correctamente."; selected.value = null; requests.value = []; await loadCard(); } catch (e) { error.value = message(e); } finally { saving.value = false; } }
onMounted(() => { void session.restore(); void Promise.all([loadCard(), loadSetup()]); }); onUnmounted(() => { searchController?.abort(); clearTimeout(searchTimer); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Operación', to: '/' }, { label: 'Tarjetas', to: '/tarjetas' }, { label: 'Gestión' }]" />
  <div class="bo-page-head"><div><p class="bo-eyebrow">Operación / Tarjetas / Gestión</p><h1>Gestionar tarjeta <span v-if="card">· {{ card.codigoTarjeta }}</span></h1><p>Administración institucional de asignación, vigencia e historial.</p></div><button class="bo-btn" @click="router.push('/tarjetas')">← Regresar al listado</button></div>
  <div v-if="error" class="bo-state-error bo-notice">{{ error }} <button class="bo-link" @click="loadCard">Reintentar</button></div><div v-if="success" class="bo-notice">{{ success }}</div>
  <div v-if="loading" class="bo-state">Cargando tarjeta...</div>
  <template v-else-if="card">
    <section class="bo-card tarjeta-summary"><div><small>Código</small><strong>{{ card.codigoTarjeta }}</strong></div><div><small>Serie</small><strong>{{ card.numeroSerie ?? "—" }}</strong></div><div><small>Estado</small><strong>{{ card.nombreEstadoTarjeta }}</strong></div><div><small>Asignación</small><strong>{{ card.idAsignacion ? card.nombreEstadoAsignacion : "Disponible" }}</strong></div><div><small>Beneficiario actual</small><strong>{{ card.nombreBeneficiario ?? "—" }}</strong></div><div><small>Perfil actual</small><strong>{{ card.perfilesAcceso ?? "—" }}</strong></div><div><small>Vigencia</small><strong>{{ card.idAsignacion ? `${card.fechaInicioVigencia?.slice(0,10)} — ${card.fechaFinVigencia?.slice(0,10) ?? "Sin vencimiento"}` : "—" }}</strong></div><div><small>Fecha de registro</small><strong>{{ new Date(card.fechaRegistro).toLocaleString('es-HN') }}</strong></div></section>
    <nav class="tarjeta-tabs" aria-label="Secciones de gestión"><button :class="{ active: tab === 'assignment' }" @click="tab = 'assignment'">Asignación</button><button :class="{ active: tab === 'history' }" @click="tab = 'history'; loadHistory()">Historial</button></nav>
    <section v-if="tab === 'assignment'" class="bo-card tarjeta-panel"><h2>Asignar beneficiario</h2><p v-if="card.idAsignacion" class="bo-form-note">Esta tarjeta ya tiene una asignación vigente. Debe finalizarse mediante el flujo operativo correspondiente antes de una nueva asignación.</p><p v-else class="bo-form-note">Busque por nombre, apellido, identidad, código de beneficiario o cuenta bancaria. Los datos sensibles se muestran enmascarados.</p><template v-if="!card.idAsignacion && canAssign"><label class="tarjeta-search">Buscar beneficiario<input v-model="search" placeholder="Escriba al menos 2 caracteres..." autocomplete="off" /></label><div v-if="resultLoading" class="bo-state">Buscando beneficiarios...</div><div v-else-if="resultError" class="bo-form-error">{{ resultError }}</div><div v-else-if="search.length >= 2 && !results.length" class="bo-state">No se encontraron beneficiarios.</div><div v-else-if="results.length" class="bo-table-wrap"><table><thead><tr><th>Nombre completo</th><th>Identificación</th><th>Código</th><th>Cuenta</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="item in results" :key="item.idBeneficiario"><td>{{ item.nombreCompleto }}</td><td>{{ masked(item.identificacionEnmascarada) }}</td><td>{{ item.codigoBeneficiario ?? '—' }}</td><td>{{ masked(item.cuentaEnmascarada) }}</td><td>Activo</td><td><button class="bo-action" @click="choose(item)">Seleccionar</button></td></tr></tbody></table><footer class="bo-pagination"><span>Página {{ resultPage }} de {{ Math.max(resultPages, 1) }}</span><div><button class="bo-page-button" :disabled="resultPage <= 1" @click="findBeneficiaries(resultPage - 1)">Anterior</button><button class="bo-page-button" :disabled="resultPage >= resultPages" @click="findBeneficiaries(resultPage + 1)">Siguiente</button></div></footer></div><div v-if="selected" class="bo-card selected-beneficiary"><strong>Beneficiario seleccionado: {{ selected.nombreCompleto }}</strong><span>{{ masked(selected.identificacionEnmascarada) }} · {{ selected.codigoBeneficiario ?? 'Sin código' }}</span><span v-if="requestLoading">Consultando solicitudes...</span><span v-else-if="!requests.length" class="bo-form-error">No tiene solicitudes válidas para asignación.</span><div v-else class="bo-form-grid"><label>Solicitud válida<select v-model="form.idSolicitud"><option value="">Seleccione...</option><option v-for="item in requests" :key="String(item.idSolicitud)" :value="String(item.idSolicitud)">{{ item.codigoSolicitud }} · {{ item.nombreEstadoSolicitud }}</option></select></label><label>Perfil de acceso autorizado<select v-model="form.idPerfilAcceso"><option value="">Sin perfil</option><option v-for="profile in profiles" :key="profile.idPerfilAcceso" :value="String(profile.idPerfilAcceso)">{{ profile.nombrePerfilAcceso }}</option></select></label><label>Tipo de vigencia<select v-model.number="form.idTipoVigencia"><option :value="0">Seleccione...</option><option v-for="item in options.tiposVigencia" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Estado de asignación<select v-model.number="form.idEstadoAsignacion"><option :value="0">Seleccione...</option><option v-for="item in options.estadosAsignacion" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Inicio de vigencia<input v-model="form.fechaInicioVigencia" type="date" /></label><label>Fin de vigencia<input v-model="form.fechaFinVigencia" type="date" /></label><button class="bo-btn bo-btn-primary bo-form-wide" :disabled="!valid || saving" @click="assign">{{ saving ? 'Registrando...' : 'Confirmar asignación' }}</button></div></div></template><p v-else class="bo-form-note">No cuenta con permiso para registrar asignaciones.</p></section>
    <section v-else-if="tab === 'history'" class="tarjeta-panel"><DataGrid :columns="historyColumns" :rows="history.map(historyRow)" :row-key="item => String(item.idAsignacion)" :pagination="{ page: historyPage, pageSize: 10, total: historyTotal, totalPages: historyPages }" :loading="historyLoading" :error="historyError" empty-text="No hay eventos históricos almacenados para esta tarjeta." @page="loadHistory"><template #cell-nombreBeneficiario="{ row }">{{ row.nombreBeneficiario }}</template><template #cell-perfilesAcceso="{ row }">{{ row.perfilesAcceso ?? "—" }}</template><template #cell-usuarioResponsable="{ row }">{{ row.usuarioResponsable ?? "—" }}</template></DataGrid></section>
  </template>
</template>
